            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is a time of quiet joy, the sunny morning. When the glittery dew is on the mallow weeds, each leaf holds a jewel which is beautiful if not valuable. This is no time for hurry or for bustle. Thoughts are slow and deep and golden in the morning.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The story was gradually taking shape. Pilon liked it this way. It ruined a story to have it all come out quickly. The good story lay in half-told things which must be filled in out of the hearer’s own experience.", Author = "John Steinbeck" },
