            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is astounding to find that the belly of every black and evil thing is as white as snow. And it is saddening to discover how the concealed parts of angels are leprous.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Ghosts could walk freely tonight, without fear of the disbelief of men; for this night was haunted, and it would be an insensitive man who did not know it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is worth while to be kind and generous,” he said. “Not only do such actions pile up a house of joy in Heaven; but there is, too, a quick reward here on earth. One feels a golden warmth glowing like a hot enchilada in one’s stomach.”", Author = "John Steinbeck" },
