            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Time is more complex near the sea than in any other place, for in addition to the circling of the sun and the turning of the seasons, the waves beat out the passage of time on the rocks and the tides rise and fall as a great clepsydra.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "His ear heard more than is said to him, and his slow speech had overtones not of thought, but of understanding beyond thought.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Guy don't need no sense to be a nice fella. Seems to me sometimes it jus' works the other way around. Take a real smart guy and he ain't hardly ever a nice fella.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Books ain't no good. A guy needs somebody - to be near him. A guy goes nuts if he ain't got nobody.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I seen too many guys with land in their head. They never get none under their hand.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Cannery Row in Monterey in California is a poem, a stink, a grating noise, a quality of light, a tone, a habit, a nostalgia, a dream.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The things we admire in men, kindness and generosity, openness, honesty, understanding and feeling are the concomitants of failure in our system. And those traits we detest, sharpness, greed, acquisitiveness, meanness, egotism and self-interest are the traits of success.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There aren't very many of them in the world, as everyone finds out sooner or later.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Having few actual perceptions, she lived by rules. Education is good. Self-control is necessary. Everything in its time and place. Travel is broadening. And it was this last axiom which had forced her finally on the vacation to Mexico.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For it is said that humans are never satisfied, that you give them one thing and they want something more. And this is said in disparagement, whereas it is one of the greatest talents the species has and one that has made it superior to animals that are satisfied with what they have.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A plan is a real thing, and things projected are experienced. A plan once made and visualized becomes a reality along with other realities-never to be destroyed but easily to be attacked.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Luck, you see, brings bitter friends.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "For every man in the world functions to the best of his ability, and no one does less than his best, no matter what he may think about it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When you argue with a child,\" she said warmly, \"you give a good argument and the child says yah, yah! You understand him and he doesn't listen, so the child wins.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He brought his malformed wisdom, his pool-hall, locker-room, joke-book wisdom to the front.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "His guard was up now and he wasn't listening; he was only angry because here was a world he could not enter and so he had to disbelieve in its existence. He fell back on the world he knew.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "\"I do understand. I understand that you are offered a loveliness and you vomit on it, that you have the gift of love given you such as few men have ever known and you throw on it the acid of your pride, your ugly twisted sense of importance.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "\"It is so easy a thing to give-only great men have the courage and courtesy and, yes, the generosity to receive.\"", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "We are no better than the animals; in fact in a lot of ways we aren't as good.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Men do change, and change comes like a little wind that ruffles the curtains at dawn, and it comes like the stealthy perfume of wildflowers hidden in the grass.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is a common experience that a problem difficult at night is resolved in the morning after the committee of sleep has worked on it.", Author = "John Steinbeck" },
