            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When a condition or a problem becomes too great, humans have the protection of not thinking about it. But it goes inward and minces up with a lot of other things already there and what comes out is discontent and uneasiness, guilt and a compulsion to get something-anything-before it is all gone.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Farewell has a sweet sound of reluctance. Good-by is short and final, a word with teeth sharp to bite through the string that ties past to the future.", Author = "John Steinbeck" },
