            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "My dreams are the problems of the day stepped up to absurdity, a little like men dancing, wearing the horns and masks of animals.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "It is odd how a man believes he can think better in a special place. I have such a place, have always had it, but I know it isn't thinking I do there, but feeling and experiencing and remembering. It's a safety place - everyone must have one, although I never heard a man tell of it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "They successfully combined piracy and puritanism, which aren't so unlike when you come right down to it. Both had a strong dislike for opposition and both had a roving eye for other people's property.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Sometimes it's great fun to be silly, like children playing statues and dying of laughter. And sometimes being silly breaks the even pace and lets you get a new start.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No man really knows about other human beings. The best he can do is to suppose that they are like himself.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Does anyone ever know even the outer fringe of another? What are you like in there? Mary - do you hear? Who are you in there?", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A man who tells secrets or stories must think of who is hearing or reading, for a story has as many versions as it has readers.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "What a wonderful thing a woman is. I can admire what they do even if I don't understand why.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Even if teen-age children aren't making a sound, it's quieter when they're gone. They put a boiling in the air around them. As they left, the whole house seemed to sigh and settle. No wonder poltergeists infest only houses with adolescent children.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "What a frightening thing is the human, a mass of gauges and dials and registers, and we can read only a few and those perhaps not accurately.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A little hope, even hopeless hope, never hurt anybody.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Can you disbelieve in something you don't know about? ... It isn't that I don't believe but that I don't know.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "To be alive at all is to have scars.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "No one wants advice - only corroboration.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In poverty she is envious. In riches she may be a snob. Money does not change the sickness, only the symptoms.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "In the dusk I saw her smile, that incredible female smile. It is called wisdom but it isn't that but rather an understanding that makes wisdom unnecessary.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The misery stayed, not thought about but aching away, and sometimes I would have to ask myself, Why do I ache? Men can get used to anything, but it takes time.", Author = "John Steinbeck" },
