            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "You know how advice is. You only want it if it agrees with what you wanted to do anyway.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "All men are moral. Only their neighbors are not.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A man is a lonely thing.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Maybe not having time to think is not having the wish to think.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Strength and success- they are above morality, above criticism. It seems then, that it is not what you do, but how you do it and what you call it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Not only the brave get killed, but the brave have a better chance of it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Good God, what a mess of draggle-tail impulses a man is - and a woman too, I guess.", Author = "John Steinbeck" },
