            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The things everyone knows are most likely to be wrong.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Like most modern people, I don't believe in prophecy or magic and then spend half my time practicing it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A crime is something someone else commits.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A secret's a terribly lonesome thing.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "There's nobody as lonely as an all-married man.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Literature is as old as speech. It grew out of human need for it, and it has not changed except to become more needed.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Faulkner, more than most men, was aware of human strength as well as of human weakness. He knew that the understanding and the resolution of fear are a large part of the writer's reason for being.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The ancient commission of the writer has not changed. He is charged with exposing our many grievous faults and failures, with dredging up to the light our dark and dangerous dreams for the purpose of improvement.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A journey is like marriage. The certain way to be wrong is to think you control it.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "When the virus of restlessness begins to take possession of a wayward man, and the road away from Here seems broad and straight and sweet, the victim must first find himself a good and sufficient reason for going.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "And now, our submarines are armed with mass murder, our silly, only way of deterring mass murder.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "A sad soul can kill you quicker, far quicker, than a germ.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "Oh, we can populate the dark with horrors, even we who think ourselves informed and sure, believing nothing we cannot measure or weigh. I know beyond all doubt that the dark things crowding in on me either did not exist or were not dangerous to me, and still I was afraid.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The mountains of things we throw away are much greater than the things we use. In this, if in no other way, we can see the wild and reckless exuberance of our production, and waste seems to be the index.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I guess this is why I hate governments. It is always the rule, the fine print, carried out by the fine print men. There's nothing to fight, no wall to hammer with frustrated fists.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "This monster of a land, this mightiest of nations, this spawn of the future, turns out to be the macrocosm of microcosm me.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "The Mojave is a big desert and a frightening one. It’s as though nature tested a man for endurance and constancy to prove whether he was good enough to get to California.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "He wasn't involved with a race that could build a thing it had to escape from.", Author = "John Steinbeck" },
            new Quote { Id = "https://en.wikiquote.org/wiki/John_Steinbeck", Text = "I wonder why progress looks so much like destruction.", Author = "John Steinbeck" },
